    function dateLabel(ymd, today) { const y = +ymd.slice(0, 4); return `${MON[+ymd.slice(5, 7) - 1]} ${+ymd.slice(8, 10)}${today && y !== +today.slice(0, 4) ? `, ${y}` : ""}`; }
