      for (const t of rows) if (t.amount_cents > 0 && !t.is_transfer && !NOT_INCOME.test(t.merchant_raw)) { const k = keyOf(t.merchant_raw); if (!by.has(k)) by.set(k, []); by.get(k).push(t); }
