    return { safeToSpend, upcoming, runway, afford, netWorth, forecast, answer, showMath, topicOf, kindOfReply, parseAmount, parseWindow, fitCadence, payStreams, payDates, todayIn, LABEL, MATH_MENU, HORIZON, STALE_MS };
